{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "name": "nd-inquisitor",
  "version": "0.1.1",
  "description": "Thin launcher for the CURRENT ND Inquisitor child under True Memory; resolves Linear NAM-352 to the authoritative Drive module.",
  "author": {
    "name": "Nameless Dhamma"
  },
  "repository": "https://github.com/namelessdhamma/nameless-dhamma-vault",
  "keywords": [
    "nameless-dhamma",
    "launcher",
    "memory",
    "forgetting",
    "currentness"
  ],
  "extensions": {
    "com.openai": {
      "interface": {
        "displayName": "ND Inquisitor",
        "shortDescription": "Launcher to the current Inquisitor module",
        "longDescription": "Thin launcher for CURRENT ND Inquisitor. Resolves stable Linear navigator NAM-352 and reads the exact StateHead-bound Drive module body before execution.",
        "developerName": "Nameless Dhamma",
        "category": "Productivity",
        "defaultPrompt": [
          "Use CURRENT ND Inquisitor through its Linear and Drive binding."
        ]
      }
    }
  }
}
